-- Epic Level Handbook monster templates and abomination framework.
-- Source: Epic Level Handbook, Chapter 5. Mechanical text is summarized; source pages remain authoritative.
-- 3.0 damage-reduction notation is preserved explicitly rather than silently converted to 3.5 materials/alignment bypasses.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('elh-3.0','epic-level-handbook-3-0','Epic Level Handbook','ELH','Wizards of the Coast','dnd','3.0',
        'Epic Level Handbook (2002): progression beyond 20th level, epic skills and feats, epic spell development, epic magic items, monsters, prestige classes, and campaign rules.',NULL,1,0,NULL);

WITH desired(slug,name,page,summary,tags,mechanics) AS (VALUES
('elh-abomination-traits','Abomination Traits','157-158',
 'Abominations are an outsider grouping descended directly or indirectly from divine beings. They share quasi-divine traits and, when Deities and Demigods is used, count as divine rank 0.',
 '["epic","monster","abomination","outsider","divine-rank-0"]',
 '{"classification":{"type":"outsider grouping","notSeparateCreatureType":true},"deitiesAndDemigodsInteraction":{"divineRank":0},"sharedTraitsNote":"Use the ELH Abomination Traits block for immunities, defenses, senses, spell-like abilities, and other common traits; individual abominations can add further abilities."}'),

('elh-template-paragon','Paragon Creature Template','209-210',
 'A paragon is an exceptional specimen of any creature. The template maximizes durability, triples movement, greatly improves defenses, attacks, abilities, skills, and special abilities, and adds epic-grade resilience.',
 '["epic","monster","template","paragon"]',
 '{"appliesTo":"any creature","typeChange":null,"hitPoints":{"maximumPerHitDie":true,"bonusPerHitDie":12},"speedMultiplier":3,"armorClass":{"insightBonus":12,"luckBonus":12,"naturalArmorBonus":5,"naturalArmorUseBetter":true},"attacks":{"luckBonus":25},"damage":{"meleeAndThrownLuckBonus":20},"specialAttacks":{"insightBonus":13,"applyAtMostOncePerSpecialAbility":true,"onlyWhenApplicable":true},"spellLikeOrPsionicCasterLevelBonus":15,"grantedSpellLikeAbilities":{"usesPerDay":3,"casterLevel":15,"abilities":["greater dispelling","haste","see invisibility"]},"resistances":{"fire":10,"cold":10,"useBetterExisting":true},"damageReduction":{"amount":20,"bypass":"+6","editionNotation":"3.0","useBetterExisting":true},"spellResistance":"base creature CR + 25; use higher existing value","fastHealing":{"amount":20,"useBetterExisting":true},"savingThrowInsightBonus":10,"abilityScoreIncrease":{"str":15,"dex":15,"con":15,"int":15,"wis":15,"cha":15},"skillCompetenceBonus":10,"bonusFeats":2,"challengeRatingAdjustment":[{"maxHitDice":6,"add":18},{"minHitDice":7,"maxHitDice":15,"add":15},{"minHitDice":16,"add":12}],"treasure":"standard for adjusted CR","alignment":"same as base creature","advancement":"same as base creature"}'),

('elh-template-pseudonatural','Epic Pseudonatural Creature Template','212-213',
 'The Epic Level Handbook pseudonatural template transforms a corporeal creature into a powerful outsider with alien tentacle attacks, extreme physical improvements, extraplanar defenses, and an alternate horrific form.',
 '["epic","monster","template","pseudonatural","outsider","far-realm"]',
 '{"appliesTo":"any corporeal creature","typeChange":"outsider","note":"This is the Epic Level Handbook version, explicitly more powerful than the Tome and Blood template.","hitPoints":{"maximumPerHitDie":true},"speedMultiplier":2,"naturalArmorBonus":35,"naturalArmorUseBetter":true,"pseudonaturalMelee":"Replace worldly-form melee attacks with at least the same number of tentacle rakes, plus table-based extra rakes; all use best attack bonus.","tentacleDamage":"2d8 + Strength modifier","constantInsight":{"attackInsightBonus":15,"ignoreConcealmentMissChance":true},"improvedGrab":{"trigger":"tentacle hit against smaller opponent","freeGrapple":true,"provokes":false},"rottingConstriction":{"trigger":"successful grapple check in later rounds","constitutionDrain":"2d4 permanent","healing":10},"spellLikeAbilities":{"uses":"at will","casterLevel":20,"abilities":["blur","dimension door","shield","unhallow"]},"spellResistance":"Hit Dice * 5; use higher existing value","resistanceAndDrTable":[{"hd":"1-3","acid":15,"electricity":15,"damageReduction":"20/+5","extraTentacles":1},{"hd":"4-7","acid":20,"electricity":20,"damageReduction":"25/+6","extraTentacles":2},{"hd":"8-11","acid":25,"electricity":25,"damageReduction":"30/+7","extraTentacles":3},{"hd":"12-15","acid":30,"electricity":30,"damageReduction":"35/+8","extraTentacles":4},{"hd":"16-19","acid":35,"electricity":35,"damageReduction":"40/+9","extraTentacles":5},{"hd":"21-24","acid":40,"electricity":40,"damageReduction":"45/+10","extraTentacles":6}],"tableContinuation":"Each additional 4 HD: +5 acid/electricity resistance, +5 DR and +1 enhancement bypass in 3.0 notation, +1 extra tentacle rake.","alternateForm":{"action":"standard","uses":"at will","mechanicsUnchanged":true,"opponentAttackMoralePenalty":-1},"abilityChanges":{"str":22,"dex":10,"con":10,"wis":10,"intMinimum":3},"challengeRatingAdjustment":[{"maxHitDice":6,"add":16},{"minHitDice":7,"maxHitDice":15,"add":13},{"minHitDice":16,"add":10}],"treasure":"same as base creature","alignment":"same as base creature","advancement":"same as base creature"}'),

('elh-template-demilich','Demilich Template','174-176',
 'A demilich is an advanced lich concentrated into a remnant such as a skull, retaining lich spellcasting while gaining exceptional magical defenses, remote phylactery-linked equipment, resistances, and greater mental ability.',
 '["epic","monster","template","demilich","lich","undead"]',
 '{"appliesTo":"any lich","spells":"retains all spells it could cast as a lich","perfectAutomaticStillSpell":true,"spellLikeAbilities":{"atWill":["alter self","astral projection","create greater undead","create undead","death knell","enervation","greater dispelling","harm","summon monster I","summon monster II","summon monster III","summon monster IV","summon monster V","summon monster VI","summon monster VII","summon monster VIII","summon monster IX","telekinesis","weird"],"twoPerDay":["greater planar ally"],"casterLevel":"spellcaster level","saveDc":"10 + demilich HD + Charisma modifier"},"magicImmunity":{"default":"immune to magical and supernatural effects","exceptions":[{"effect":"shatter","result":"treated as crystalline; half normal damage"},{"effect":"dispel evil","result":"3d6 damage; Fortitude half"},{"effect":"holy smite","result":"normal effect"}]},"phylacteryTransference":"Wearable magic items kept near the phylactery transfer their benefits to the demilich regardless of distance, subject to normal item-slot limits.","immunities":["cold","electricity","polymorph","mind-affecting attacks"],"turnResistance":20,"damageReduction":{"amount":30,"bypass":"none","editionNotation":"3.0 source says 30/—","vorpalException":"Vorpal weapons ignore DR but deal half damage; demilich cannot be beheaded."},"resistances":{"acid":20,"sonic":20},"abilityChanges":{"int":10,"wis":10,"cha":10},"racialSkillBonuses":{"hide":20,"listen":20,"moveSilently":20,"search":20,"senseMotive":20,"spot":20},"flightFaq":{"naturalFlySpeedFeet":180,"maneuverability":"perfect","naturalFlightFunctionsInAntimagic":true,"supernaturalFlightMayAlsoBeRetained":true}}'),

('elh-template-worm-that-walks','Worm That Walks Template','228-230',
 'An evil wizard or sorcerer can return as a colony of worms that retains the character’s magic and equipment while gaining engulfing vermin attacks, extraordinary senses, spell resistance, frightful presence, and discorporation.',
 '["epic","monster","template","worm-that-walks","ooze","arcane"]',
 '{"appliesTo":"evil wizard or sorcerer","typeChange":"ooze","hitDie":8,"oozeBonusHitPointsBySize":true,"armorClass":{"insightBonus":20},"retainsSpecialAttacks":true,"engulf":{"maximumTargetSize":"one category larger","attack":"melee touch","initialDamage":100,"damagePerRound":100,"escape":"full-round action; then may move up to half speed","constructsImmune":true},"spells":"retains all spells it could cast while living","spellLikeAbilities":{"usesPerDay":1,"casterLevel":20,"abilities":["animal friendship (vermin)","animal growth (vermin)","animal messenger (vermin)","animal shapes (vermin)","animal trance (vermin)","colossal vermin","creeping doom","giant vermin","summon swarm (vermin)","summon vermin","vermin plague"]},"blindsightFeet":300,"spellResistance":"Challenge Rating + 10","frightfulPresence":{"trigger":"engulf","save":"Will","dc":"10 + half HD + Charisma modifier","duration":"1d4 rounds","success":"shaken","failBy1To5":"frightened","failBy6To10":"panicked","failBy11OrMore":"cowering","seenBeforeSaveBonus":5,"engulfedVictimSavePenalty":-5},"discorporate":{"action":"free","result":"falls into individual component vermin","reformsIfAnySurvive":true,"equipmentRisk":true},"racialSkillBonuses":{"hide":20,"intuitDirection":20,"listen":20,"moveSilently":20},"challengeRatingAdjustment":3,"alignment":"any evil","advancement":"by character class","ritualCreation":{"preparation":"burial ground tended for a year and a day; blood each new moon and raw meat each full moon","gpCost":10000,"xpCost":2000,"requiredSpells":["limited wish","polymorph any object","summon swarm heightened to 7th level","sympathy"],"chance":"1% per prepared uncast arcane spell or unused spontaneous spell slot","riseDelay":"1d4 days"}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'elh-rule-'||d.slug,'elh-3.0',d.page,d.slug,d.name,d.summary,d.summary,0,NULL,1,
       'monster-template','subsystem',0,1,NULL,NULL,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='elh-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
